"""Embedded preserved evidence for v1.7 T-7 source recovery.

Generated from the original v1.6.1/v1.7 Library artifacts. The payloads are
gzip-compressed CSV encoded as base64 to keep the forensic workflow
self-contained without committing binary archives/joblibs.
"""
from __future__ import annotations

import base64
import gzip
from pathlib import Path

BASE_CSV_GZ_B64 = ""

V161_T7_OOS_GZ_B64 = ""

V17_T7_OOS_GZ_B64 = ""


def materialize(directory: Path) -> dict[str, Path]:
    directory.mkdir(parents=True, exist_ok=True)
    mapping = {
        "v17_t7_base.csv": BASE_CSV_GZ_B64,
        "t7_walkforward_predictions_v161.csv": V161_T7_OOS_GZ_B64,
        "t7_walkforward_v17.csv": V17_T7_OOS_GZ_B64,
    }
    output = {}
    for filename, payload in mapping.items():
        path = directory / filename
        path.write_bytes(gzip.decompress(base64.b64decode(payload)))
        output[filename] = path
    return output
